```ts
import type { CoreClient, MergedReportRecord, OpenedGame, ParsedReport, RememberedRegion } from "@atlantis/core-client";
import type { ImportStatus } from "./workspace/AppHeader";
import { commitTurn, rememberTurn, type MemoryOutcome } from "./gameMemory";
import { documentFor, draftKeyFor } from "./orderDraft";
import { decideReportLoad } from "./reportLoadDecision";
import { buildHexMapModel, unitsForHex } from "./hexMapModel";
import { warningStatus } from "./workspace/shellStatus";

/** Everything a turn brings to the screen, read before any of it is shown. */
export type LoadedTurn = {
  parsed: ParsedReport;
  rawReport: string;
  remembered: RememberedRegion[];
  merged: MergedReportRecord[];
  orders: string;
  ordersSavedAt: string | null;
  /** The counts, and the remember/draft warning if there was one - `applyReport`'s status (:996-1004). */
  status: ImportStatus;
};

/**
 * Reads everything a report needs to become the working turn: commits it (unless COMMITTED says a
 * batch already has - see `applyReport`'s note on why committing twice loses the ally's account),
 * reads back the map, and chooses saved orders over the report's template. No game: nothing is
 * remembered and the template is the document. Rejects when the commit or the read does; the
 * caller reports and applies nothing.
 */
export async function loadTurn(
  client: CoreClient, game: OpenedGame | null, report: ParsedReport, text: string,
  rulesetText: string | null, now: string, committed?: MemoryOutcome
): Promise<LoadedTurn>;

/** The hex and unit to land on when a turn opens into an empty selection (:1013-1022), or null. */
export function openingSelection(report: ParsedReport): { regionId: string; unitId: string | null } | null;

/** Commits an older report for history and says so; the screen is not touched (gh-208, :1048-1084). */
export async function storeOlderTurn(
  client: CoreClient, game: OpenedGame, report: ParsedReport, text: string, rulesetText: string | null,
  now: string, currentTurn: number
): Promise<ImportStatus>;   // warningStatus(warning ?? `turn ${n} stored for history; still showing turn ${currentTurn}.`)

/** Moved from AppShell.tsx:244-260 with its doc comment; exported because the shell holds one in state. */
export type PendingReportLoad = { … as today … };

export type ReportRoute =
  | { kind: "load" }
  | { kind: "storeOnly"; currentTurn: number }
  | { kind: "ask"; pending: PendingReportLoad };

/**
 * Where a parsed report goes: `decideReportLoad` plus the prompt's snapshot (:1105-1130) - the
 * viewer's identity is taken here, when the question is raised, never when it is answered.
 */
export function routeReport(
  viewer: ParsedReport | null, report: ParsedReport, text: string, fileName: string
): ReportRoute;

/** The parse the shell uses everywhere: classified when the ruleset is to hand, full otherwise (:1097-1100). */
export function reportParser(
  client: Pick<CoreClient, "parseReportClassified" | "parseReportFull">,
  ruleset: { status: "ready"; text: string } | { status: string }
): (text: string) => Promise<ParsedReport>;
```

