    // than in a second pass, because the loop already has each hex's own units and their orders.
    let mut producing: BTreeSet<&str> = BTreeSet::new();
    let mut taxing: BTreeSet<&str> = BTreeSet::new();
    let mut first_produce: Option<(&str, &str, &PlacedIntent)> = None;
```

inside it, after `let hex = Hex::read(region, &ordered);` and the `hex.units.is_empty()` guard:

```rust
